-height:18px;text-overflow:ellipsis;white-space:nowrap;box-shadow:0 4px 10px rgba(15,23,42,.16)}.gantt-bar.progress{background:#d97706}.gantt-bar.done{background:#16a34a}.gantt-edit{margin-top:8px}.gantt-edit summary{cursor:pointer;color:#2563eb;font-size:12px}.gantt-edit-form{display:grid;grid-template-columns:1fr 1fr auto;gap:6px;margin-top:7px}.gantt-edit-form input,.gantt-edit-form button{min-width:0;padding:6px;font-size:11px}.gantt-empty{padding:36px;text-align:center;color:#6b7280}.gantt-backlog{margin-top:20px}.gantt-backlog h3{margin:0 0 10px}.gantt-backlog-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:10px}.gantt-backlog-card{padding:13px;border:1px dashed #cbd5e1;border-radius:10px;background:#f8fafc}.gantt-backlog-card strong,.gantt-backlog-card small{display:block}.gantt-backlog-card small{margin-top:5px;color:#6b7280}@media(max-width:650px){.gantt{padding:14px}.gantt-head{flex-direction:column}.gantt-row{grid-template-columns:220px minmax(calc(var(--slot-count) * var(--slot-width)),1fr)}.gantt-board{min-width:max(650px,calc(220px + var(--slot-count) * var(--slot-width)))}.gantt-task{padding:10px}.gantt-edit-form{grid-template-columns:1fr}.gantt-edit-form button{width:100%}}html[data-theme="dark"] .gantt{background:#1e293b;border-color:#475569}html[data-theme="dark"] .gantt-scroll,html[data-theme="dark"] .gantt-row,html[data-theme="dark"] .gantt-task{border-color:#334155}html[data-theme="dark"] .gantt-task{background:#1e293b}html[data-theme="dark"] .gantt-header,html[data-theme="dark"] .gantt-header .gantt-task,html[data-theme="dark"] .gantt-backlog-card{background:#0f172a}html[data-theme="dark"] .gantt-calendar{background:repeating-linear-gradient(90deg,transparent 0,transparent calc((100% / var(--slot-count)) - 1px),#334155 calc((100% / var(--slot-count)) - 1px),#334155 calc(100% / var(--slot-count)))}html[data-theme="dark"] .gantt-head p,html[data-theme="dark"] .gantt-meta,html[data-theme="dark"] .gantt-backlog-card small{color:#94a3b8}html[data-theme="dark"] .gantt-date,html[data-theme="dark"] .gantt-date b{color:#cbd5e1}html[data-theme="dark"] .gantt-period{background:#172554;color:#bfdbfe}
</style>
<section class="gantt" style="--slot-count:<?= $slotCount ?>;--slot-width:<?= $stepDays === 1 ? '54px' : '76px' ?>">
<header class="gantt-head"><div><h2>İş zaman şeması</h2><p>Görevlerin hangi tarihlerde ve kim tarafından yürütüleceğini gösterir.</p></div><?php if ($scheduled !== []): ?><span class="gantt-period"><?= date('d.m.Y', $rangeStart) ?> — <?= date('d.m.Y', $rangeEnd) ?></span><?php endif ?></header>
<?php if ($scheduled === []): ?><div class="gantt-empty">Şemada gösterilecek tarihli bir iş bulunmuyor. Yeni iş oluştururken başlangıç ve bitiş tarihi ekleyebilirsin.</div><?php else: ?>
<div class="gantt-scroll"><div class="gantt-board"><div class="gantt-row gantt-header"><div class="gantt-task">Görev / sorumlu</div><div class="gantt-calendar"><?php foreach ($slots as $slot): ?><div class="gantt-date"><b><?= date('d', $slot) ?></b><?= $stepDays === 1 ? date('M', $slot) : date('d.m', $slot) ?></div><?php endforeach ?></div></div>
<?php foreach ($scheduled as $item): ?><?php
$start = strtotime($item['start_date'] ?: $item['due_date']); $end = strtotime($item['due_date'] ?: $item['start_date']);
if ($end < $start) [$start, $end] = [$end, $start];
$startColumn = (int) floor(($start - $rangeStart) / (86400 * $stepDays)) + 1;
$endColumn = (int) floor(($end - $rangeStart) / (86400 * $stepDays)) + 2;
$statusClass = $statusClasses[$item['status']] ?? 'todo';
?><div class="gantt-row"><div class="gantt-task"><strong><?= esc($item['title']) ?></strong><div class="gantt-meta"><i class="gantt-dot <?= $statusClass ?>"></i><span><?= esc($statusLabels[$item['status']] ?? $item['status']) ?></span><span>·</span><span><?= esc($item['assignee_username'] ?: 'Atanmamış') ?></span></div><?php if ($isOwner): ?><details class="gantt-edit"><summary>Tarihleri düzenle</summary><form class="gantt-edit-form" method="post" action="<?= site_url('projects/'.$project['id'].'/items/'.$item['id'].'/schedule') ?>"><?= csrf_field() ?><input type="date" name="start_date" value="<?= esc($item['start_date']) ?>" aria-label="Başlangıç tarihi"><input type="date" name="due_date" value="<?= esc($item['due_date']) ?>" aria-label="Bitiş tarihi"><button class="button" type="submit">Kaydet</button></form></details><?php endif ?></div><div class="gantt-calendar"><span class="gantt-bar <?= $statusClass ?>" style="grid-column:<?= $startColumn ?> / <?= $endColumn ?>" title="<?= esc($item['title'], 'attr') ?>"><?= esc($item['title']) ?></span></div></div><?php endforeach ?>
</div></div><?php endif ?>
<?php if ($unscheduled !== []): ?><section class="gantt-backlog"><h3>Tarihi belirlenmemiş işler · <?= count($unscheduled) ?></h3><div class="gantt-backlog-list"><?php foreach ($unscheduled as $item): ?><article class="gantt-backlog-card"><strong><?= esc($item['title']) ?></strong><small><?= esc($item['assignee_username'] ?: 'Atanmamış') ?></small><?php if ($isOwner): ?><details class="gantt-edit"><summary>Şemaya ekle</summary><form class="gantt-edit-form" method="post" action="<?= site_url('projects/'.$project['id'].'/items/'.$item['id'].'/schedule') ?>"><?= csrf_field() ?><input type="date" name="start_date" aria-label="Başlangıç tarihi"><input type="date" name="due_date" aria-label="Bitiş tarihi"><button class="button" type="submit">Ekle</button></form></details><?php endif ?></article><?php endforeach ?></div></section><?php endif ?>
